; trail ant (gradient + food trail); generated by ants/gen-trail.ts, do not edit by hand
; start of a trip: uniform random heading (0..5 turns), then arrive on the nest cell
start: flipzero 6 else s1
  goto a0
s1: flipzero 5 else s2
  turn left
  goto a0
s2: flipzero 4 else s3
  turn left
  turn left
  goto a0
s3: flipzero 3 else s4
  turn left
  turn left
  turn left
  goto a0
s4: flipzero 2 else s5
  turn right
  turn right
  goto a0
s5: turn right
  goto a0
; delivery: shared by all phases
rd: drop
  goto start
; carrier lost (no code under it): walk randomly until a coded cell is found
lost: sense here home else lw
  goto rd
lw: flipzero 3 else lw1
  turn left
  goto lm
lw1: flipzero 2 else lm
  turn right
lm: move else lw
  goto ls0
ls0: sense here marker 0 else ls1
  goto r0
ls1: sense here marker 1 else ls2
  goto r1
ls2: sense here marker 2 else lost
  goto r2
; ---- phase 0 ----
; explorer arrival: sync with the code under us, or write ours
a0: sense here marker 0 else a0b
  goto x0
a0b: sense here marker 1 else a0c
  goto x1
a0c: sense here marker 2 else a0d
  goto x2
a0d: mark 0
  goto x0
; explorer decision: food here, food ahead/left/right (never on the nest), food trail, wander
x0: sense here food else x0a
  sense here home else x0pk
  goto x0a
x0pk: pickup else x0a
  mark 3
  turn left
  turn left
  turn left
  goto r0
x0a: sense ahead food else x0b
  sense ahead home else m0
  goto x0b
x0b: sense leftahead food else x0c
  sense leftahead home else x0bl
  goto x0c
x0bl: turn left
  goto m0
x0c: sense rightahead food else x0t
  sense rightahead home else x0cr
  goto x0t
x0cr: turn right
  goto m0
x0t: sense here marker 3 else x0j
  sense ahead marker 3 else x0tl
  sense ahead marker 1 else x0tl
  goto m0
x0tl: sense leftahead marker 3 else x0tr
  sense leftahead marker 1 else x0tr
  turn left
  goto m0
x0tr: sense rightahead marker 3 else x0end
  sense rightahead marker 1 else x0end
  turn right
  goto m0
x0end: flipzero 4 else x0w
  unmark 3
  goto x0w
x0j: sense ahead marker 3 else x0w
  sense ahead marker 1 else x0w
  goto m0
x0w: flipzero 5 else x0wt
  goto m0
x0wt: flipzero 2 else x0wr
  turn left
  goto m0
x0wr: turn right
  goto m0
m0: move else x0rot
  goto a1
x0rot: flipzero 2 else x0rr
  turn left
  goto x0
x0rr: turn right
  goto x0
; carrier at a cell with code p: drop if on the nest, enter the nest if it is ahead, else follow code p-1
r0: sense here home else r0a
  goto rd
r0a: sense ahead home else r0g
  goto rh0
rh0: move else r0
  goto rd
r0g: sense ahead marker 2 else r0gl
  goto rm0
r0gl: sense leftahead marker 2 else r0gr
  sense rightahead marker 2 else r0tl
  flipzero 2 else r0trr
r0tl: turn left
  goto rm0
r0trr: turn right
  goto rm0
r0gr: sense rightahead marker 2 else r0hl
  turn right
  goto rm0
r0hl: sense leftahead home else r0hr
  turn left
  goto rh0
r0hr: sense rightahead home else lost
  turn right
  goto rh0
rm0: move else r0
  goto ra2
; carrier arrival: mark the way, then sync with the code under us
ra0: mark 3
  sense here marker 0 else ra0b
  goto r0
ra0b: sense here marker 1 else ra0c
  goto r1
ra0c: sense here marker 2 else lost
  goto r2
; ---- phase 1 ----
; explorer arrival: sync with the code under us, or write ours
a1: sense here marker 1 else a1b
  goto x1
a1b: sense here marker 2 else a1c
  goto x2
a1c: sense here marker 0 else a1d
  goto x0
a1d: mark 1
  goto x1
; explorer decision: food here, food ahead/left/right (never on the nest), food trail, wander
x1: sense here food else x1a
  sense here home else x1pk
  goto x1a
x1pk: pickup else x1a
  mark 3
  turn left
  turn left
  turn left
  goto r1
x1a: sense ahead food else x1b
  sense ahead home else m1
  goto x1b
x1b: sense leftahead food else x1c
  sense leftahead home else x1bl
  goto x1c
x1bl: turn left
  goto m1
x1c: sense rightahead food else x1t
  sense rightahead home else x1cr
  goto x1t
x1cr: turn right
  goto m1
x1t: sense here marker 3 else x1j
  sense ahead marker 3 else x1tl
  sense ahead marker 2 else x1tl
  goto m1
x1tl: sense leftahead marker 3 else x1tr
  sense leftahead marker 2 else x1tr
  turn left
  goto m1
x1tr: sense rightahead marker 3 else x1end
  sense rightahead marker 2 else x1end
  turn right
  goto m1
x1end: flipzero 4 else x1w
  unmark 3
  goto x1w
x1j: sense ahead marker 3 else x1w
  sense ahead marker 2 else x1w
  goto m1
x1w: flipzero 5 else x1wt
  goto m1
x1wt: flipzero 2 else x1wr
  turn left
  goto m1
x1wr: turn right
  goto m1
m1: move else x1rot
  goto a2
x1rot: flipzero 2 else x1rr
  turn left
  goto x1
x1rr: turn right
  goto x1
; carrier at a cell with code p: drop if on the nest, enter the nest if it is ahead, else follow code p-1
r1: sense here home else r1a
  goto rd
r1a: sense ahead home else r1g
  goto rh1
rh1: move else r1
  goto rd
r1g: sense ahead marker 0 else r1gl
  goto rm1
r1gl: sense leftahead marker 0 else r1gr
  sense rightahead marker 0 else r1tl
  flipzero 2 else r1trr
r1tl: turn left
  goto rm1
r1trr: turn right
  goto rm1
r1gr: sense rightahead marker 0 else r1hl
  turn right
  goto rm1
r1hl: sense leftahead home else r1hr
  turn left
  goto rh1
r1hr: sense rightahead home else lost
  turn right
  goto rh1
rm1: move else r1
  goto ra0
; carrier arrival: mark the way, then sync with the code under us
ra1: mark 3
  sense here marker 1 else ra1b
  goto r1
ra1b: sense here marker 2 else ra1c
  goto r2
ra1c: sense here marker 0 else lost
  goto r0
; ---- phase 2 ----
; explorer arrival: sync with the code under us, or write ours
a2: sense here marker 2 else a2b
  goto x2
a2b: sense here marker 0 else a2c
  goto x0
a2c: sense here marker 1 else a2d
  goto x1
a2d: mark 2
  goto x2
; explorer decision: food here, food ahead/left/right (never on the nest), food trail, wander
x2: sense here food else x2a
  sense here home else x2pk
  goto x2a
x2pk: pickup else x2a
  mark 3
  turn left
  turn left
  turn left
  goto r2
x2a: sense ahead food else x2b
  sense ahead home else m2
  goto x2b
x2b: sense leftahead food else x2c
  sense leftahead home else x2bl
  goto x2c
x2bl: turn left
  goto m2
x2c: sense rightahead food else x2t
  sense rightahead home else x2cr
  goto x2t
x2cr: turn right
  goto m2
x2t: sense here marker 3 else x2j
  sense ahead marker 3 else x2tl
  sense ahead marker 0 else x2tl
  goto m2
x2tl: sense leftahead marker 3 else x2tr
  sense leftahead marker 0 else x2tr
  turn left
  goto m2
x2tr: sense rightahead marker 3 else x2end
  sense rightahead marker 0 else x2end
  turn right
  goto m2
x2end: flipzero 4 else x2w
  unmark 3
  goto x2w
x2j: sense ahead marker 3 else x2w
  sense ahead marker 0 else x2w
  goto m2
x2w: flipzero 5 else x2wt
  goto m2
x2wt: flipzero 2 else x2wr
  turn left
  goto m2
x2wr: turn right
  goto m2
m2: move else x2rot
  goto a0
x2rot: flipzero 2 else x2rr
  turn left
  goto x2
x2rr: turn right
  goto x2
; carrier at a cell with code p: drop if on the nest, enter the nest if it is ahead, else follow code p-1
r2: sense here home else r2a
  goto rd
r2a: sense ahead home else r2g
  goto rh2
rh2: move else r2
  goto rd
r2g: sense ahead marker 1 else r2gl
  goto rm2
r2gl: sense leftahead marker 1 else r2gr
  sense rightahead marker 1 else r2tl
  flipzero 2 else r2trr
r2tl: turn left
  goto rm2
r2trr: turn right
  goto rm2
r2gr: sense rightahead marker 1 else r2hl
  turn right
  goto rm2
r2hl: sense leftahead home else r2hr
  turn left
  goto rh2
r2hr: sense rightahead home else lost
  turn right
  goto rh2
rm2: move else r2
  goto ra1
; carrier arrival: mark the way, then sync with the code under us
ra2: mark 3
  sense here marker 2 else ra2b
  goto r2
ra2b: sense here marker 0 else ra2c
  goto r0
ra2c: sense here marker 1 else lost
  goto r1
